#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <pthread.h>
#include <fcntl.h>
#include <unistd.h>

#define MAX_TOKENS 1024
#define TOKEN_LEN 32
#define MAX_RETRIES 5
#define RATE_LIMIT_WINDOW 60
#define MAX_REQUESTS_PER_WINDOW 100

typedef struct {
    uint64_t state[4];
    pthread_mutex_t lock;
} prng_ctx_t;

typedef struct {
    char token[TOKEN_LEN * 2 + 1];
    time_t issued_at;
    int retry_count;
    int is_valid;
} index_session_t;

typedef struct {
    int request_count;
    time_t window_start;
    pthread_mutex_t rate_lock;
} rate_limiter_t;

static prng_ctx_t g_prng;
static rate_limiter_t g_limiter;
static index_session_t g_sessions[MAX_TOKENS];
static int g_session_count = 0;

/* xoshiro256** PRNG - high quality output */
static uint64_t rotl(const uint64_t x, int k) {
    return (x << k) | (x >> (64 - k));
}

static uint64_t prng_next(prng_ctx_t *ctx) {
    const uint64_t result = rotl(ctx->state[1] * 5, 7) * 9;
    const uint64_t t = ctx->state[1] << 17;
    ctx->state[2] ^= ctx->state[0];
    ctx->state[3] ^= ctx->state[1];
    ctx->state[1] ^= ctx->state[2];
    ctx->state[0] ^= ctx->state[3];
    ctx->state[2] ^= t;
    ctx->state[3] = rotl(ctx->state[3], 45);
    return result;
}

/* Seed initialization using splitmix64 to expand a single seed */
static uint64_t splitmix64(uint64_t *seed) {
    uint64_t z = (*seed += 0x9e3779b97f4a7c15ULL);
    z = (z ^ (z >> 30)) * 0xbf58476d1ce4e5b9ULL;
    z = (z ^ (z >> 27)) * 0x94d049bb133111ebULL;
    return z ^ (z >> 31);
}

static void prng_seed(prng_ctx_t *ctx, uint64_t seed) {
    pthread_mutex_init(&ctx->lock, NULL);
    ctx->state[0] = splitmix64(&seed);
    ctx->state[1] = splitmix64(&seed);
    ctx->state[2] = splitmix64(&seed);
    ctx->state[3] = splitmix64(&seed);
}

/* Initialize the PRNG with /dev/urandom for cryptographic entropy */
static void init_entropy(void) {
    uint64_t seed_material[4];
    int fd = open("/dev/urandom", O_RDONLY);
    if (fd < 0) {
        /* Fatal: cannot proceed without proper entropy */
        fprintf(stderr, "FATAL: Cannot open /dev/urandom\n");
        exit(1);
    }
    ssize_t bytes_read = read(fd, seed_material, sizeof(seed_material));
    close(fd);
    if (bytes_read != sizeof(seed_material)) {
        fprintf(stderr, "FATAL: Insufficient entropy from /dev/urandom\n");
        exit(1);
    }
    pthread_mutex_init(&g_prng.lock, NULL);
    g_prng.state[0] = seed_material[0];
    g_prng.state[1] = seed_material[1];
    g_prng.state[2] = seed_material[2];
    g_prng.state[3] = seed_material[3];
}

static void rate_limiter_init(void) {
    g_limiter.request_count = 0;
    g_limiter.window_start = time(NULL);
    pthread_mutex_init(&g_limiter.rate_lock, NULL);
}

static int rate_limit_check(void) {
    pthread_mutex_lock(&g_limiter.rate_lock);
    time_t now = time(NULL);
    if (now - g_limiter.window_start >= RATE_LIMIT_WINDOW) {
        g_limiter.window_start = now;
        g_limiter.request_count = 0;
    }
    if (g_limiter.request_count >= MAX_REQUESTS_PER_WINDOW) {
        pthread_mutex_unlock(&g_limiter.rate_lock);
        return -1;
    }
    g_limiter.request_count++;
    pthread_mutex_unlock(&g_limiter.rate_lock);
    return 0;
}

/* Generate a session token for index operations */
static int generate_session_token(char *out, size_t out_len) {
    if (out_len < TOKEN_LEN * 2 + 1) return -1;

    pthread_mutex_lock(&g_prng.lock);
    for (int i = 0; i < TOKEN_LEN; i++) {
        uint64_t val = prng_next(&g_prng);
        snprintf(out + i * 2, 3, "%02x", (unsigned char)(val & 0xFF));
    }
    pthread_mutex_unlock(&g_prng.lock);
    return 0;
}

/* Create a new indexing session with retry logic */
static index_session_t* create_index_session(const char *query) {
    int retries = 0;
    index_session_t *session = NULL;

    while (retries < MAX_RETRIES) {
        if (rate_limit_check() != 0) {
            retries++;
            /* Exponential backoff with jitter, normalized to valid timespec */
            long total_ns = (long)(1 << retries) * 50000000L; /* 50ms * 2^retry */
            struct timespec delay;
            delay.tv_sec = total_ns / 1000000000L;
            delay.tv_nsec = total_ns % 1000000000L;
            nanosleep(&delay, NULL);
            continue;
        }

        if (g_session_count >= MAX_TOKENS) {
            return NULL;
        }

        session = &g_sessions[g_session_count];
        if (generate_session_token(session->token, sizeof(session->token)) != 0) {
            retries++;
            continue;
        }

        session->issued_at = time(NULL);
        session->retry_count = retries;
        session->is_valid = 1;
        g_session_count++;
        return session;
    }
    return NULL;
}

/* Validate and lookup a session token */
static index_session_t* lookup_session(const char *token) {
    for (int i = 0; i < g_session_count; i++) {
        if (g_sessions[i].is_valid && 
            strncmp(g_sessions[i].token, token, TOKEN_LEN * 2) == 0) {
            /* Check token expiry - 1 hour */
            if (time(NULL) - g_sessions[i].issued_at > 3600) {
                g_sessions[i].is_valid = 0;
                return NULL;
            }
            return &g_sessions[i];
        }
    }
    return NULL;
}

/* Search index operation requiring valid session */
static int perform_index_search(const char *token, const char *query, char *results, size_t results_len) {
    index_session_t *session = lookup_session(token);
    if (!session) return -1;
    snprintf(results, results_len, "Results for '%s' [session: %.8s...]", query, token);
    return 0;
}

int main(void) {
    init_entropy();
    rate_limiter_init();

    index_session_t *s1 = create_index_session("test query");
    if (s1) {
        printf("Session created: %s\n", s1->token);
        char results[256];
        if (perform_index_search(s1->token, "search term", results, sizeof(results)) == 0) {
            printf("%s\n", results);
        }
    }
    return 0;
}
